70	const FILLER = new Set(["a", "an", "the", "some", "new", "mod", "cool", "awesome", "i", "want", "need", "like", "really"]);
71	const FLAVOR: [RegExp, string][] = [
72	  [/fire|flame|burn|ember|lava/, "Ember"],
73	  [/frost|ice|freez|snow|cold/, "Frost"],
74	  [/lightning|storm|thunder|shock/, "Storm"],
75	  [/shadow|dark|void|night/, "Void"],
76	  [/moon|lunar|star|cosmic|nebula/, "Lunar"],
77	  [/neon|cyber|hack|chrome/, "Neon"],
