159	  const b = count(next);
160	  let additions = 0;
161	  let deletions = 0;
162	  for (const [line, n] of b) additions += Math.max(0, n - (a.get(line) ?? 0));
163	  for (const [line, n] of a) deletions += Math.max(0, n - (b.get(line) ?? 0));
