/* ═════════════ Valheim · BepInEx 5 · HarmonyX · C# (Jötunn where it pulls its weight) ═════════════ */

type Dmg = "m_frost" | "m_fire" | "m_lightning" | "m_poison" | "m_spirit";

/** Valheim code per effect. TARGET is the Character being hit, SOURCE the attacker, POWER a float expression. */
interface VFx {
  /** HitData.DamageTypes field the effect adds. */
  dmg?: Dmg;
  /** Vanilla crafting material its recipes ask for. */
  mat: string;
  hit?: string;
  /** Runs once per proc on SOURCE. */
  self?: string;
  /** `self` only compiles when SOURCE is a Player. */
  player?: boolean;
}

const addSE = (name: string, on = "TARGET") => `${on}.GetSEMan().AddStatusEffect("${name}".GetStableHashCode(), resetTime: true)`;

const VFX: Record<EffectKey, VFx> = {
  frost: { dmg: "m_frost", mat: "FreezeGland", hit: `TARGET.GetSEMan().AddStatusEffect(ObjectDB.instance.GetStatusEffect("Frost".GetStableHashCode()), resetTime: true);` },
  fire: { dmg: "m_fire", mat: "SurtlingCore", hit: `(${addSE("Burning")} as SE_Burning)?.AddFireDamage(POWER);` },
  storm: { dmg: "m_lightning", mat: "Thunderstone", hit: `Object.Instantiate(ZNetScene.instance.GetPrefab("lightningAOE"), TARGET.transform.position, Quaternion.identity);` },
  blink: { mat: "GreydwarfEye", player: true, self: `SOURCE.TeleportTo(SOURCE.transform.position + SOURCE.transform.forward * RADIUS, SOURCE.transform.rotation, distantTeleport: false);` },
  heal: { mat: "Bloodbag", self: `SOURCE.Heal(POWER * 0.5f, showText: true);` },
  poison: { dmg: "m_poison", mat: "Guck", hit: `(${addSE("Poison")} as SE_Poison)?.AddDamage(POWER);` },
  summon: { mat: "BoneFragments", self: `Object.Instantiate(ZNetScene.instance.GetPrefab("Skeleton_Friendly"), SOURCE.transform.position + SOURCE.transform.right * 2f, SOURCE.transform.rotation);` },
  flight: { mat: "Feathers", self: `${addSE("SlowFall", "SOURCE")}; // the feather cape's effect` },
  void: { mat: "Ectoplasm", hit: `${addSE("Smoked")};\n${addSE("Wet")};` },
  lunar: {
    mat: "Crystal",
    hit: `if (EnvMan.instance.IsNight())\n{\n    var moonlight = new HitData { m_point = TARGET.GetCenterPoint() };\n    moonlight.m_damage.m_spirit = POWER * 0.5f;\n    moonlight.SetAttacker(SOURCE);\n    TARGET.Damage(moonlight);\n}`,
  },
  // auto ships its own Smelter / Fermenter patch (see productionPatch).
  auto: { mat: "Bronze" },
  neon: { mat: "Crystal", player: true, self: `SOURCE.Message(MessageHud.MessageType.TopLeft, "<color=#ff4fd8>LABEL</color>");` },
};

const DMG_TYPE: Record<Dmg, string> = { m_frost: "Frost", m_fire: "Fire", m_lightning: "Lightning", m_poison: "Poison", m_spirit: "Spirit" };

/** Biome keywords → Heightmap.Biome, a vanilla location to clone, its treasure chest and vegetation worth thickening. */
const BIOMES: [RegExp, string, string, string, string[]][] = [
  [/mountain|snow|frost|ice|icy|glacier|peak|blizzard|cold/, "Mountain", "DrakeNest01", "TreasureChest_mountains", ["FirTree", "MineRock_Obsidian"]],
  [/swamp|bog|marsh|toxic|poison|plague|rot/, "Swamp", "SunkenCrypt4", "TreasureChest_swamp", ["SwampTree1"]],
  [/plains|desert|savanna|fire|ember|lava|ash|sun/, "Plains", "GoblinCamp2", "TreasureChest_plains_stone", ["Birch1", "Pickable_Barley_Wild", "Pickable_Flax_Wild"]],
  [/forest|wood|grove|dark|shadow|void|troll/, "BlackForest", "Crypt2", "TreasureChest_blackforest", ["FirTree", "Pinetree_01", "MineRock_Tin"]],
  [/./, "Meadows", "WoodHouse1", "TreasureChest_meadows", ["Beech1", "Oak1"]],
];

interface Ctx {
  input: TemplateInput;
  k: CategoryKey;
  cls: string;
  snake: string;
  n: ReturnType<typeof numbers>;
  fx: Effect[];
  /** Plugin and balance class names. */
  P: string;
  B: string;
  text: string;
