/* ───────────── config entries: one list drives the C# binds and the .cfg BepInEx writes ───────────── */

type SType = "bool" | "float" | "int" | "key";
interface Setting {
  section: string;
  key: string;
  type: SType;
  def: number | boolean | string;
  desc: string;
  range?: [number, number];
}
const fl = (section: string, key: string, def: number, desc: string, range: [number, number]): Setting => ({ section, key, type: "float", def, desc, range });
const nt = (section: string, key: string, def: number, desc: string, range: [number, number]): Setting => ({ section, key, type: "int", def: Math.round(def), desc, range });
const bl = (section: string, key: string, def: boolean, desc: string): Setting => ({ section, key, type: "bool", def, desc });
const hk = (section: string, key: string, def: string, desc: string): Setting => ({ section, key, type: "key", def, desc });

const CS_TYPE: Record<SType, string> = { bool: "bool", float: "float", int: "int", key: "KeyboardShortcut" };
const CFG_TYPE: Record<SType, string> = { bool: "Boolean", float: "Single", int: "Int32", key: "KeyboardShortcut" };
const lit = (s: Setting, v = s.def) => (s.type === "float" ? `${v}f` : s.type === "key" ? `new KeyboardShortcut(KeyCode.${v})` : String(v));

function bindLine(s: Setting) {
  const t = CS_TYPE[s.type];
  const desc = s.range ? `new ConfigDescription("${s.desc}", new AcceptableValueRange<${t}>(${lit(s, s.range[0])}, ${lit(s, s.range[1])}))` : `"${s.desc}"`;
  return `${s.key} = Config.Bind("${s.section}", "${s.key}", ${lit(s)}, ${desc});`;
}

function cfgFile(c: Ctx, settings: Setting[]) {
  const out = [`## Settings file was created by plugin ${c.input.modName} v${c.input.version}.0.0`, `## Plugin GUID: com.cyrus.${c.snake}`, ""];
  for (const section of [...new Set(settings.map((s) => s.section))].sort()) {
    out.push(`[${section}]`, "");
    for (const s of settings.filter((x) => x.section === section).sort((a, b) => a.key.localeCompare(b.key))) {
      out.push(`## ${s.desc}`, `# Setting type: ${CFG_TYPE[s.type]}`, `# Default value: ${s.def}`);
      if (s.range) out.push(`# Acceptable value range: From ${s.range[0]} to ${s.range[1]}`);
      out.push(`${s.key} = ${s.def}`, "");
    }
  }
  return out.join("\n");
}

/** What each archetype contributes to the project. */
interface ArchOut {
  settings: Setting[];
  /** Second file: the patch that makes the mod work. */
  main: ModFile;
  extra: ModFile[];
  words: Record<string, string>;
  /** Members of the pure, unit-tested balance class. */
  balance: string;
  tests: string;
  prefab?: string;
  jotunn?: boolean;
  awake?: string;
  usings?: string[];
  /** Extra managed assemblies from valheim_Data/Managed. */
  refs?: string[];
}

/* ───────────── effect snippet helpers ───────────── */

const has = (c: Ctx, key: EffectKey) => c.fx.some((e) => e.key === key);
const fill = (c: Ctx, s: string, target: string, source: string, power: string) =>
  sub(s, target, source, { POWER: power, RADIUS: `${c.n.radius}f`, LABEL: c.input.modName });
const dmgsOf = (c: Ctx) => [...new Set(c.fx.map((e) => VFX[e.key].dmg).filter((d): d is Dmg => !!d))];
const hits = (c: Ctx, target: string, source: string, power: string) =>
  c.fx.flatMap((e) => (VFX[e.key].hit ? [fill(c, VFX[e.key].hit!, target, source, power)] : []));
const selfs = (c: Ctx, source: string, power: string, isPlayer: boolean, skip: EffectKey[] = []) =>
  c.fx.flatMap((e) => {
    const v = VFX[e.key];
    return v.self && (isPlayer || !v.player) && !skip.includes(e.key) ? [fill(c, v.self, "", source, power)] : [];
  });

/** A HitData carrying the effects' elemental damage (blunt when none apply). */
function strike(c: Ctx, target: string, source: string, power: string) {
  const d = dmgsOf(c);
  return code`
    var strike = new HitData { m_point = ${target}.GetCenterPoint() };
    ${(d.length ? d : ["m_blunt"]).map((x) => `strike.m_damage.${x} = ${power};`)}
    strike.SetAttacker(${source});
    ${target}.Damage(strike);`;
}

/** Pulses every effect through the enemies around `src` (a Player). */
function castBlock(c: Ctx, src: string, power: string, radius: string) {
  return code`
    var targets = new List<Character>();
    Character.GetCharactersInRange(${src}.transform.position, ${radius}, targets);
    foreach (var target in targets)
    {
        if (target == ${src} || target.IsDead() || !BaseAI.IsEnemy(${src}, target)) continue;
        ${strike(c, "target", src, power)}
        ${hits(c, "target", src, power)}
    }
    ${selfs(c, src, power, true)}`;
}

/** On-hit body for a Character.Damage postfix, re-entrancy guarded because effects can deal damage themselves. */
function onHit(c: Ctx, target: string, source: string, power: string, isPlayer: boolean) {
  let body = [...hits(c, target, source, power), ...selfs(c, source, power, isPlayer)];
  if (!body.length) body = [strike(c, target, source, power)];
  return code`
    _applying = true;
    try
    {
        ${body}
    }
    finally
    {
        _applying = false;
    }`;
}

/* ───────────── entry point ───────────── */

export function valheimBepInEx(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const k = input.category.key;
  const c: Ctx = {
    input,
    k,
    cls,
    snake,
    n: numbers(input),
    fx: effectsFor(input),
    P: `${cls}Plugin`,
    B: `${cls}Balance`,
    text: `${input.prompt} ${input.modName}`.toLowerCase(),
  };
  const arch = ARCH[k];
  const a =
    arch === "item" ? (k === "magic" ? magicArch(c) : itemArch(c)) : arch === "entity" ? entityArch(c) : arch === "world" ? worldArch(c) : arch === "system" ? systemArch(c) : visualArch(c);

  const settings = [bl("General", "Enabled", true, "Master switch for everything this mod adds."), ...a.settings];
  if (has(c, "auto")) {
    settings.push(fl("Production", "ProductionSpeed", Number((1 + c.n.intensity).toFixed(2)), "Speed multiplier for smelters, kilns, fermenters and cooking stations.", [1, 10]));
    if (a.main.path !== "src/Patches/ProductionPatch.cs") a.extra.push(productionPatch(c));
  }

  const files = [pluginFile(c, a, settings), a.main, csproj(c, a), ...a.extra, manifest(c, a)];
  return { files, config: file(`config/com.cyrus.${snake}.cfg`, cfgFile(c, settings)), l10n: l10nFile(c, a), test: testFile(c, a) };
}

function pluginFile(c: Ctx, a: ArchOut, settings: Setting[]): ModFile {
  const { input, cls, P, B } = c;
  const vNote = input.version > 1 ? `// v${input.version}: retuned the numbers and moved every one of them into the BepInEx config.` : "";
  return file(
    `src/${P}.cs`,
    code`
      using BepInEx;
      using BepInEx.Configuration;
      using BepInEx.Logging;
      using HarmonyLib;
      ${a.jotunn ? ["using Jotunn.Managers;", "using Jotunn.Utils;"] : ""}
      ${a.usings ?? ""}
      using UnityEngine;

      namespace ${cls}
      {
          /// <summary>${input.modName}: ${input.category.label.toLowerCase()} for Valheim. Forged by Cyrus (${MODEL_NAME[input.model]}) v${input.version}.</summary>
          ${vNote}
          [BepInPlugin(PluginGUID, PluginName, PluginVersion)]
          ${a.jotunn ? ["[BepInDependency(Jotunn.Main.ModGuid)]", "[NetworkCompatibility(CompatibilityLevel.EveryoneMustHaveMod, VersionStrictness.Minor)]"] : ""}
          public class ${P} : BaseUnityPlugin
          {
              public const string PluginGUID = "com.cyrus.${c.snake}";
              public const string PluginName = "${input.modName}";
              public const string PluginVersion = "${input.version}.0.0";
              ${a.prefab ? `public const string PrefabName = "${a.prefab}";` : ""}

              internal static ManualLogSource Log;

              ${settings.map((s) => `public static ConfigEntry<${CS_TYPE[s.type]}> ${s.key};`)}

              private Harmony _harmony;

              private void Awake()
              {
                  Log = Logger;
                  BindConfig();

                  _harmony = new Harmony(PluginGUID);
                  _harmony.PatchAll();
                  ${a.awake ?? ""}

                  Logger.LogInfo($"{PluginName} v{PluginVersion} loaded");
              }

              private void BindConfig()
              {
                  ${settings.map(bindLine)}
              }

              private void OnDestroy() => _harmony?.UnpatchSelf();
          }

          /// <summary>Pure balance math with no Unity types, so it can be unit tested outside the game.</summary>
          public static class ${B}
          {
              ${a.balance}

              public static float Clamp(float value, float min, float max) => value < min ? min : value > max ? max : value;

              public static int Clamp(int value, int min, int max) => value < min ? min : value > max ? max : value;
          }
      }`,
  );
}

function csproj(c: Ctx, a: ArchOut): ModFile {
  const ref = (name: string, dir = "$(ManagedPath)", extra = "") => `<Reference Include="${name}" HintPath="${dir}\\${name}.dll" Private="false"${extra} />`;
  const managed = ["assembly_utils", "UnityEngine", "UnityEngine.CoreModule", ...(a.refs ?? [])];
  return file(
    `${c.cls}.csproj`,
    code`
      <Project Sdk="Microsoft.NET.Sdk">

        <PropertyGroup>
          <TargetFramework>net48</TargetFramework>
          <AssemblyName>${c.cls}</AssemblyName>
          <RootNamespace>${c.cls}</RootNamespace>
          <Version>${c.input.version}.0.0</Version>
          <LangVersion>latest</LangVersion>
          <AllowUnsafeBlocks>true</AllowUnsafeBlocks>
          <VALHEIM_INSTALL Condition="'$(VALHEIM_INSTALL)' == ''">C:\\Program Files (x86)\\Steam\\steamapps\\common\\Valheim</VALHEIM_INSTALL>
          <BepInExPath>$(VALHEIM_INSTALL)\\BepInEx</BepInExPath>
          <ManagedPath>$(VALHEIM_INSTALL)\\valheim_Data\\Managed</ManagedPath>
        </PropertyGroup>

        <ItemGroup>
          <Compile Remove="tests\\**" />
          ${a.jotunn ? `<Translations Include="Translations\\**\\*.json" />` : ""}
        </ItemGroup>

        <ItemGroup>
          <!-- Publicized assembly_valheim: private members like ZNetScene.m_namedPrefabs and Player.Update are reachable. -->
          <PackageReference Include="BepInEx.AssemblyPublicizer.MSBuild" Version="0.4.2" PrivateAssets="all" />
          ${a.jotunn ? `<PackageReference Include="JotunnLib" Version="2.20.1" />` : ""}
        </ItemGroup>

        <ItemGroup>
          ${ref("BepInEx", "$(BepInExPath)\\core")}
          ${ref("0Harmony", "$(BepInExPath)\\core")}
          ${ref("assembly_valheim", "$(ManagedPath)", ` Publicize="true"`)}
          ${managed.map((m) => ref(m))}
        </ItemGroup>

        <Target Name="DeployToBepInEx" AfterTargets="Build" Condition="Exists('$(BepInExPath)\\plugins')">
          <Copy SourceFiles="$(TargetPath)" DestinationFolder="$(BepInExPath)\\plugins\\$(AssemblyName)" />
          ${a.jotunn ? `<Copy SourceFiles="@(Translations)" DestinationFolder="$(BepInExPath)\\plugins\\$(AssemblyName)\\%(RecursiveDir)" />` : ""}
        </Target>

      </Project>`,
  );
}

function manifest(c: Ctx, a: ArchOut): ModFile {
  const deps = ["denikson-BepInExPack_Valheim-5.4.2202", ...(a.jotunn ? ["ValheimModding-Jotunn-2.20.1"] : [])];
  return file(
    "manifest.json",
    JSON.stringify({ name: c.cls, version_number: `${c.input.version}.0.0`, website_url: "", description: deriveFeatures(c.input)[0].slice(0, 250), dependencies: deps }, null, 2) + "\n",
  );
}

function l10nFile(c: Ctx, a: ArchOut): ModFile {
  if (a.jotunn) return file(`Translations/English/${c.snake}.json`, JSON.stringify(a.words, null, 2) + "\n");
  return file(
    "src/Patches/LocalizationPatch.cs",
    code`
      using System.Collections.Generic;
      using HarmonyLib;

      namespace ${c.cls}.Patches
      {
          /// <summary>Adds the mod's $tokens whenever Valheim (re)loads a language. Other languages fall back to English.</summary>
          [HarmonyPatch(typeof(Localization), nameof(Localization.SetupLanguage))]
          public static class LocalizationPatch
          {
              private static readonly Dictionary<string, string> English = new Dictionary<string, string>
              {
                  ${Object.entries(a.words).map(([key, text]) => `{ "${key}", "${text}" },`)}
              };

              private static void Postfix(Localization __instance)
              {
                  foreach (var pair in English) __instance.AddWord(pair.Key, pair.Value);
              }
          }
      }`,
  );
}

function testFile(c: Ctx, a: ArchOut): ModFile {
  return file(
    `tests/${c.cls}.Tests/${c.B}Tests.cs`,
    code`
      using Xunit;

      namespace ${c.cls}.Tests
      {
          public class ${c.B}Tests
          {
              ${a.tests}

              [Theory]
              [InlineData(-5f, 0f)]
              [InlineData(0.35f, 0.35f)]
              [InlineData(9f, 1f)]
              public void ClampKeepsConfigValuesInRange(float raw, float expected) =>
                  Assert.Equal(expected, ${c.B}.Clamp(raw, 0f, 1f));
          }
      }`,
  );
}

/** Speeds up every production building; the `auto` effect's patch. */
function productionPatch(c: Ctx): ModFile {
  const { cls, P } = c;
  return file(
    "src/Patches/ProductionPatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;

      namespace ${cls}.Patches
      {
          /// <summary>Each building keeps its own copy of these fields, so scaling them in Awake is per-instance and safe.</summary>
          [HarmonyPatch]
          public static class ProductionPatch
          {
              // Smelter covers the smelter, blast furnace, charcoal kiln, spinning wheel and windmill.
              [HarmonyPatch(typeof(Smelter), nameof(Smelter.Awake)), HarmonyPostfix]
              private static void SmelterAwake(Smelter __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  __instance.m_secPerProduct /= ${P}.ProductionSpeed.Value;
                  __instance.m_maxOre = Mathf.RoundToInt(__instance.m_maxOre * Mathf.Sqrt(${P}.ProductionSpeed.Value));
              }

              [HarmonyPatch(typeof(Fermenter), nameof(Fermenter.Awake)), HarmonyPostfix]
              private static void FermenterAwake(Fermenter __instance)
              {
                  if (${P}.Enabled.Value) __instance.m_fermentationDuration /= ${P}.ProductionSpeed.Value;
              }

              [HarmonyPatch(typeof(CookingStation), nameof(CookingStation.Awake)), HarmonyPostfix]
              private static void CookingStationAwake(CookingStation __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  foreach (var conversion in __instance.m_conversion) conversion.m_cookTime /= ${P}.ProductionSpeed.Value;
              }
          }
      }`,
  );
}

