input.new_string:
/* ───────────── item: weapons, items (vanilla ObjectDB) and magic (Jötunn) ───────────── */

const WEAPONS: [RegExp, string][] = [
  [/battle ?axe|great ?axe/, "Battleaxe"],
  [/axe/, "AxeIron"],
  [/great ?sword|claymore/, "THSwordKrom"],
  [/mace|hammer|club|maul/, "MaceIron"],
  [/spear|javelin/, "SpearElderbark"],
  [/atgeir|glaive|halberd|polearm/, "AtgeirIron"],
  [/crossbow|arbalest/, "CrossbowArbalest"],
  [/bow/, "BowFineWood"],
  [/knife|dagger/, "KnifeSilver"],
];
const STAFFS: Partial<Record<EffectKey, string>> = { frost: "StaffIceShards", storm: "StaffLightning", summon: "StaffSkeleton", heal: "StaffShield" };

const itemBalance = code`
  /// <summary>Share of the base elemental damage added per upgrade (Valheim's m_damagesPerLevel).</summary>
  public const float PerLevelRatio = 0.25f;

  /// <summary>Mirrors ItemDrop.ItemData.GetDamage: base + perLevel * (quality - 1), capped at four upgrades.</summary>
  public static float DamageAtQuality(float baseDamage, int quality) => baseDamage + baseDamage * PerLevelRatio * (Clamp(quality, 1, 4) - 1);

  public static bool Procs(float chance, float roll) => roll < Clamp(chance, 0f, 1f);`;

function itemTests(c: Ctx, dmg: number) {
  const at = (q: number) => Number((dmg * (1 + 0.25 * (q - 1))).toFixed(2));
  return code`
    [Theory]
    [InlineData(1, ${at(1)}f)]
    [InlineData(3, ${at(3)}f)]
    [InlineData(4, ${at(4)}f)]
    public void ElementalDamageScalesPerUpgrade(int quality, float expected) =>
        Assert.Equal(expected, ${c.B}.DamageAtQuality(${dmg}f, quality), 2);

    [Fact]
    public void QualityIsCappedAtFour() =>
        Assert.Equal(${c.B}.DamageAtQuality(${dmg}f, 4), ${c.B}.DamageAtQuality(${dmg}f, 9));

    [Fact]
    public void ProcChanceIsClampedToCertainty()
    {
        Assert.True(${c.B}.Procs(5f, 0.999f));
        Assert.False(${c.B}.Procs(-1f, 0f));
    }`;
}

/** Character.Damage postfix firing the effects when the local player hits with this mod's item. */
function weaponHitPatch(c: Ctx): ModFile {
  const { cls, P, B } = c;
  return file(
    `src/Patches/${cls}HitPatch.cs`,
    code`
      using System.Collections.Generic;
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          /// <summary>Character.Damage runs on the attacker's client, so the effects fire where the swing happened.</summary>
          [HarmonyPatch(typeof(Character), nameof(Character.Damage))]
          public static class ${cls}HitPatch
          {
              private static bool _applying;

              private static void Postfix(Character __instance, HitData hit)
              {
                  if (_applying || !${P}.Enabled.Value || hit == null || __instance.IsDead()) return;
                  if (!(hit.GetAttacker() is Player player) || player != Player.m_localPlayer) return;

                  var weapon = player.GetCurrentWeapon();
                  if (weapon?.m_dropPrefab == null || weapon.m_dropPrefab.name != ${P}.PrefabName) return;
                  if (!${B}.Procs(${P}.ProcChance.Value, Random.value)) return;

                  var power = ${P}.Power.Value;
                  ${onHit(c, "__instance", "player", "power", true)}
              }
          }
      }`,
  );
}

/** Hotkey ability while the item is equipped (non-weapon items). */
function abilityPatch(c: Ctx): ModFile {
  const { cls, P } = c;
  return file(
    `src/Patches/${cls}AbilityPatch.cs`,
    code`
      using System.Collections.Generic;
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          [HarmonyPatch(typeof(Player), nameof(Player.Update))]
          public static class ${cls}AbilityPatch
          {
              private static float _cooldown;

              private static void Postfix(Player __instance)
              {
                  if (__instance != Player.m_localPlayer || !${P}.Enabled.Value) return;
                  if (_cooldown > 0f)
                  {
                      _cooldown -= Time.deltaTime;
                      return;
                  }
                  if (!__instance.TakeInput() || !${P}.AbilityKey.Value.IsDown()) return;

                  var equipped = __instance.GetInventory().GetEquippedItems().Find(i => i.m_dropPrefab && i.m_dropPrefab.name == ${P}.PrefabName);
                  if (equipped == null) return;

                  ${castBlock(c, "__instance", `${P}.Power.Value`, `${P}.Radius.Value`)}
                  _cooldown = ${P}.AbilityCooldown.Value;
              }
          }
      }`,
  );
}

function itemArch(c: Ctx): ArchOut {
  const { cls, snake, P, B, n, k, input } = c;
  const kind =
    k === "weapons" ? "weapon" : /food|potion|mead|drink|stew|soup|elixir|tonic|brew/.test(c.text) ? "consumable" : /pickaxe|pick|tool|mining|drill/.test(c.text) ? "tool" : "trinket";
  const base =
    kind === "weapon" ? (WEAPONS.find(([re]) => re.test(c.text))?.[1] ?? "SwordIron") : kind === "consumable" ? "MeadHealthMinor" : kind === "tool" ? "PickaxeIron" : "BeltStrength";
  const recipeFrom = kind === "consumable" ? "MeadBaseHealthMinor" : base;
  const dmgs = dmgsOf(c).length ? dmgsOf(c) : (["m_spirit"] as Dmg[]);
  const elemental = Number((n.power * 4).toFixed(1));
  const mats = [...new Set(c.fx.map((e) => VFX[e.key].mat))];
  const reqs: [string, number, number][] =
    kind === "consumable"
      ? [["Honey", 10, 0], ["Blueberries", 5, 0], ...mats.map((m): [string, number, number] => [m, 2, 0])]
      : [[kind === "trinket" ? "Silver" : "Iron", 20, 10], [kind === "trinket" ? "LeatherScraps" : "ElderBark", 6, 2], ...mats.map((m, i): [string, number, number] => [m, i ? 4 : 8, i ? 2 : 4])];
  const status = kind !== "weapon";

  const settings: Setting[] =
    kind === "weapon"
      ? [
          fl("Item", "ElementalDamage", elemental, "Elemental damage added on top of the base weapon.", [0, 300]),
          fl("Item", "AttackForce", Math.round(40 + n.power * 2), "Knockback applied on hit.", [0, 200]),
          fl("Effects", "ProcChance", n.chance, "Chance for on-hit effects to trigger.", [0, 1]),
          fl("Effects", "Power", n.power, "Strength of the on-hit effects.", [1, 50]),
        ]
      : [
          kind === "consumable"
            ? fl("Item", "DurationSeconds", n.duration * 60, "How long the effect lasts.", [30, 3600])
            : nt("Item", "CarryWeight", n.interval * 15, "Extra carry weight while equipped.", [0, 300]),
          fl("Item", "RegenMultiplier", Number((1 + n.power / 20).toFixed(2)), "Health regeneration multiplier.", [1, 3]),
          ...(kind === "tool" ? [fl("Item", "MiningDamage", Math.round(n.power * 8), "Pickaxe damage against rock and ore.", [1, 300])] : []),
          ...(kind === "consumable"
            ? []
            : [
                hk("Hotkeys", "AbilityKey", "G", "Activates the equipped item's ability."),
                fl("Ability", "AbilityCooldown", n.cooldown, "Seconds between ability uses.", [0.5, 120]),
                fl("Ability", "Radius", n.radius, "Ability radius in meters.", [1, 30]),
                fl("Effects", "Power", n.power, "Strength of the ability's effects.", [1, 50]),
              ]),
        ];

  const configure =
    kind === "weapon"
      ? [
          ...dmgs.flatMap((d) => [`shared.m_damages.${d} = ${P}.ElementalDamage.Value;`, `shared.m_damagesPerLevel.${d} = ${P}.ElementalDamage.Value * ${B}.PerLevelRatio;`]),
          `shared.m_attackForce = ${P}.AttackForce.Value;`,
          has(c, "frost") ? `shared.m_attackStatusEffect = db.GetStatusEffect("Frost".GetStableHashCode());` : "",
        ]
      : kind === "consumable"
        ? [`shared.m_consumeStatusEffect = CreateStatus(db, shared);`]
        : [
            kind === "tool" ? `shared.m_damages.m_pickaxe = ${P}.MiningDamage.Value;\nshared.m_toolTier += 1;` : "",
            `shared.m_equipStatusEffect = CreateStatus(db, shared);`,
          ];

  const main = file(
    "src/Patches/ItemRegistration.cs",
    code`
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          /// <summary>Clones ${base} into ${cls}, registers it with ObjectDB (item + recipe) and ZNetScene (network prefab).</summary>
          [HarmonyPatch]
          public static class ItemRegistration
          {
              private const string BasePrefab = "${base}";
              ${status ? `private const string StatusName = "SE_${cls}";` : ""}
              private static GameObject _prefab;
              private static GameObject _container;

              [HarmonyPatch(typeof(ObjectDB), nameof(ObjectDB.Awake)), HarmonyPostfix]
              private static void ObjectDBAwake(ObjectDB __instance) => Register(__instance);

              [HarmonyPatch(typeof(ObjectDB), nameof(ObjectDB.CopyOtherDB)), HarmonyPostfix]
              private static void ObjectDBCopyOtherDB(ObjectDB __instance) => Register(__instance);

              [HarmonyPatch(typeof(ZNetScene), nameof(ZNetScene.Awake)), HarmonyPostfix]
              private static void ZNetSceneAwake(ZNetScene __instance)
              {
                  var prefab = GetOrCreate(__instance.GetPrefab(BasePrefab));
                  if (!prefab || __instance.m_namedPrefabs.ContainsKey(prefab.name.GetStableHashCode())) return;
                  __instance.m_prefabs.Add(prefab);
                  __instance.m_namedPrefabs.Add(prefab.name.GetStableHashCode(), prefab);
              }

              private static void Register(ObjectDB db)
              {
                  // The main-menu ObjectDB starts empty; wait for the populated one.
                  if (db.m_items.Count == 0 || !db.GetItemPrefab("Amber")) return;
                  var prefab = GetOrCreate(db.GetItemPrefab(BasePrefab));
                  if (!prefab) return;

                  var shared = prefab.GetComponent<ItemDrop>().m_itemData.m_shared;
                  shared.m_name = "$item_${snake}";
                  shared.m_description = "$item_${snake}_description";
                  ${configure}

                  if (db.GetItemPrefab(prefab.name)) return;
                  db.m_items.Add(prefab);
                  db.m_itemByHash[prefab.name.GetStableHashCode()] = prefab;
                  db.m_recipes.Add(CreateRecipe(db, prefab));
                  ${P}.Log.LogInfo($"Registered {prefab.name} (cloned from {BasePrefab})");
              }

              private static GameObject GetOrCreate(GameObject source)
              {
                  if (_prefab || !source) return _prefab;
                  if (!_container)
                  {
                      // Inactive parent: the clone's Awake/ZNetView never run until the game instantiates it.
                      _container = new GameObject("${cls}_Prefabs");
                      _container.SetActive(false);
                      Object.DontDestroyOnLoad(_container);
                  }
                  _prefab = Object.Instantiate(source, _container.transform, false);
                  _prefab.name = ${P}.PrefabName;
                  return _prefab;
              }

              private static Recipe CreateRecipe(ObjectDB db, GameObject prefab)
              {
                  var template = db.GetRecipe(db.GetItemPrefab("${recipeFrom}").GetComponent<ItemDrop>().m_itemData);
                  var recipe = ScriptableObject.CreateInstance<Recipe>();
                  recipe.name = "Recipe_" + prefab.name;
                  recipe.m_item = prefab.GetComponent<ItemDrop>();
                  recipe.m_amount = 1;
                  recipe.m_craftingStation = template ? template.m_craftingStation : null;
                  recipe.m_minStationLevel = template ? template.m_minStationLevel + 1 : 1;
                  recipe.m_resources = new[]
                  {
                      ${reqs.map(([item, amount, per]) => `Requirement(db, "${item}", ${amount}, ${per}),`)}
                  };
                  return recipe;
              }

              private static Piece.Requirement Requirement(ObjectDB db, string item, int amount, int perLevel) => new Piece.Requirement
              {
                  m_resItem = db.GetItemPrefab(item).GetComponent<ItemDrop>(),
                  m_amount = amount,
                  m_amountPerLevel = perLevel,
                  m_recover = true,
              };
              ${
                status
                  ? code`

                    private static StatusEffect CreateStatus(ObjectDB db, ItemDrop.ItemData.SharedData shared)
                    {
                        var existing = db.GetStatusEffect(StatusName.GetStableHashCode());
                        if (existing) return existing;

                        var status = ScriptableObject.CreateInstance<SE_Stats>();
                        status.name = StatusName;
                        status.m_name = "$se_${snake}";
                        status.m_tooltip = "$se_${snake}_tooltip";
                        status.m_icon = shared.m_icons[0];
                        status.m_ttl = ${kind === "consumable" ? `${P}.DurationSeconds.Value` : "0f"};
                        status.m_healthRegenMultiplier = ${P}.RegenMultiplier.Value;
                        ${kind === "consumable" ? "" : `status.m_addMaxCarryWeight = ${P}.CarryWeight.Value;`}
                        ${dmgsOf(c).map((d) => `status.m_mods.Add(new HitData.DamageModPair { m_type = HitData.DamageType.${DMG_TYPE[d]}, m_modifier = HitData.DamageModifier.Resistant });`)}
                        db.m_StatusEffects.Add(status);
                        return status;
                    }`
                  : ""
              }
          }
      }`,
  );

  const desc = deriveFeatures(input)[0];
  return {
    settings,
    main,
    extra: kind === "weapon" ? [weaponHitPatch(c)] : kind === "consumable" ? [] : [abilityPatch(c)],
    words: {
      [`item_${snake}`]: input.modName,
      [`item_${snake}_description`]: desc,
      ...(status ? { [`se_${snake}`]: input.modName, [`se_${snake}_tooltip`]: `${desc}.` } : {}),
    },
    balance: itemBalance,
    tests: itemTests(c, elemental),
    prefab: cls,
  };
}

function magicArch(c: Ctx): ArchOut {
  const { cls, snake, P, B, n, input } = c;
  const base = c.fx.map((e) => STAFFS[e.key]).find(Boolean) ?? "StaffFireball";
  const dmgs = dmgsOf(c).length ? dmgsOf(c) : (["m_spirit"] as Dmg[]);
  const dmg = Number((n.power * 5).toFixed(1));
  const mats = [...new Set(c.fx.map((e) => VFX[e.key].mat))];
  const main = file(
    `src/Items/${cls}Staff.cs`,
    code`
      using Jotunn.Configs;
      using Jotunn.Entities;
      using Jotunn.Managers;
      using UnityEngine;

      namespace ${cls}.Items
      {
          /// <summary>Builds the staff from ${base} through Jötunn once vanilla prefabs are available.</summary>
          internal static class ${cls}Staff
          {
              private const string BasePrefab = "${base}";

              public static void Register()
              {
                  try
                  {
                      var staff = new CustomItem(${P}.PrefabName, BasePrefab, new ItemConfig
                      {
                          Name = "$item_${snake}",
                          Description = "$item_${snake}_description",
                          CraftingStation = CraftingStations.GaldrTable,
                          MinStationLevel = 2,
                          Requirements = new[]
                          {
                              new RequirementConfig("YggdrasilWood", 12, 4),
                              new RequirementConfig("Eitr", 16, 8),
                              ${mats.map((m) => `new RequirementConfig("${m}", 8, 4),`)}
                          },
                      });

