/* ───────────── entity: creatures, characters (companions), vehicles (mounts and ships) ───────────── */

/** Prompt keywords → vanilla prefab to clone, spawn biome and whether it eats meat. */
const CREATURES: [RegExp, string, string, boolean][] = [
  [/drake|dragon|wyvern|wyrm/, "Hatchling", "Mountain", true],
  [/wolf|wolves|hound|fenring/, "Wolf", "Mountain", true],
  [/boar|pig|hog/, "Boar", "Meadows", false],
  [/lox|mammoth/, "Lox", "Plains", false],
  [/troll|giant|ogre/, "Troll", "BlackForest", true],
  [/deer|stag|elk/, "Deer", "Meadows", false],
  [/serpent|eel|leviathan/, "Serpent", "Ocean", true],
  [/asksvin|askvin|lizard|raptor/, "Asksvin", "AshLands", true],
  [/seeker|spider|insect|bug/, "Seeker", "Mistlands", true],
  [/draugr|undead|zombie|ghoul/, "Draugr", "Swamp", true],
  [/skeleton|bone/, "Skeleton", "BlackForest", true],
  [/golem|stone/, "StoneGolem", "Mountain", true],
  [/wraith|ghost|phantom/, "Wraith", "Swamp", true],
  [/slime|blob|ooze/, "Blob", "Swamp", true],
  [/surtling|imp/, "Surtling", "Swamp", true],
];
const FX_CREATURE: Partial<Record<EffectKey, string>> = { frost: "Hatchling", storm: "Hatchling", flight: "Hatchling", void: "Wraith", poison: "Blob", summon: "Skeleton", fire: "Surtling" };
const SHIPS: [RegExp, string][] = [
  [/karve/, "Karve"],
  [/raft/, "Raft"],
  [/ship|boat|longship|drakkar|sail|galley|vessel/, "VikingShip"],
];

const entityBalance = code`
  /// <summary>Valheim multiplies a creature's base health by its level (one star = level 2).</summary>
  public static float HealthAtLevel(float baseHealth, int level) => baseHealth * System.Math.Max(1, level);

  /// <summary>Seconds of feeding still needed before Tameable flips the creature to tamed.</summary>
  public static float TamingLeft(float tamingTime, float fedSeconds) => System.Math.Max(0f, tamingTime - fedSeconds);`;

function entityArch(c: Ctx): ArchOut {
  const { cls, snake, P, n, k, input } = c;
  const ship = k === "vehicles" ? SHIPS.find(([re]) => re.test(c.text))?.[1] : undefined;
  if (ship) return shipArch(c, ship);

  const companion = k === "characters";
  const mount = k === "vehicles";
  const pick = CREATURES.find(([re]) => re.test(c.text)) ?? CREATURES.find(([, p]) => p === c.fx.map((e) => FX_CREATURE[e.key]).find(Boolean));
  const [, base, biome, meat] = companion ? [/./, "Dverger", "Mistlands", true] : mount ? (pick && /Lox|Asksvin/.test(pick[1]) ? pick : CREATURES[3]) : (pick ?? CREATURES[1]);
  const ride = mount || /\bride|riding|rideable|mount|saddle/.test(c.text);
  const tame = !companion && (ride || /tam(e|ing|able)|pet|companion|friend|loyal/.test(c.text));
  const weather = has(c, "frost") ? "SnowStorm" : has(c, "storm") ? "ThunderStorm" : "";
  const dmgs = dmgsOf(c);
  const Reg = companion ? "CompanionRegistration" : mount ? "MountRegistration" : "CreatureRegistration";
  const foods = meat ? ["RawMeat", "DeerMeat", "LoxMeat"] : ["Carrot", "Turnip", "Barley", "Cloudberry"];

  const settings: Setting[] = [
    fl(companion ? "Companion" : "Creature", "Health", n.health, "Base health before star scaling.", [10, 10000]),
    fl(companion ? "Companion" : "Creature", "SpeedBonus", n.speed, "Extra run speed as a fraction of the base creature.", [0, 2]),
    ...(dmgs.length ? [fl("Effects", "ElementalDamage", Number((n.power * 3).toFixed(1)), "Elemental damage added to every attack.", [0, 300])] : []),
    fl("Effects", "Power", n.power, "Strength of the creature's effects.", [1, 50]),
    ...(tame ? [fl("Taming", "TamingTime", n.duration * 150, "Seconds of feeding needed to tame.", [30, 7200])] : []),
    ...(ride ? [fl("Riding", "RideStamina", 120 + n.radius * 20, "Saddle stamina while ridden.", [20, 1000]), fl("Riding", "AbilityCooldown", n.cooldown, "Seconds between rider buffs.", [0.5, 120])] : []),
    ...(companion
      ? [hk("Hotkeys", "SummonKey", "H", "Summons your companion, or calls it back to you."), fl("Companion", "RegenPerSecond", Number((n.power / 2).toFixed(1)), "Health regained each second.", [0, 50])]
      : [
