                      Requirement(__instance, "ElderBark", 40),
                      Requirement(__instance, "IronNails", 80),
                      Requirement(__instance, "DeerHide", 10),
                      Requirement(__instance, "${mat}", 8),
                  };

                  __instance.m_prefabs.Add(_prefab);
                  __instance.m_namedPrefabs[_prefab.name.GetStableHashCode()] = _prefab;
