              private static void ObjectDBAwake(ObjectDB __instance) => AddToHammer(__instance);

              private static void AddToHammer(ObjectDB db)
              {
                  if (!_prefab || !db) return;
                  var hammer = db.GetItemPrefab("Hammer");
                  var pieces = hammer ? hammer.GetComponent<ItemDrop>().m_itemData.m_shared.m_buildPieces.m_pieces : null;
                  if (pieces != null && !pieces.Contains(_prefab)) pieces.Add(_prefab);
