              {
                  var player = Player.m_localPlayer;
                  if (!player || !${P}.Enabled.Value || __instance.m_lastHit?.GetAttacker() != player) return;
                  ${nightOnly ? "if (!EnvMan.instance.IsNight()) return; // the hunt only counts under the moon" : ""}

                  int kills = Kills(player);
                  int perStage = ${P}.KillsPerStage.Value;
                  int stage = ${B}.StageFor(kills, perStage, Targets.Length);
                  if (stage >= Targets.Length || Utils.GetPrefabName(__instance.gameObject) != Targets[stage]) return;

                  kills++;
                  player.m_customData[KillsKey] = kills.ToString();
                  if (${B}.StageFor(kills, perStage, Targets.Length) == stage)
                  {
                      MessageHud.instance.ShowMessage(MessageHud.MessageType.TopLeft,
                          Localization.instance.Localize("$${snake}_progress", ${B}.ProgressInStage(kills, perStage).ToString(), perStage.ToString()));
                      return;
                  }

                  Reward(player, stage);
                  if (stage + 1 < Targets.Length)
                  {
                      var next = ZNetScene.instance.GetPrefab(Targets[stage + 1]).GetComponent<Character>().m_name;
                      MessageHud.instance.ShowMessage(MessageHud.MessageType.Center,
                          Localization.instance.Localize("$${snake}_stage", (stage + 2).ToString(), Localization.instance.Localize(next)));
                  }
              }

              public static int Kills(Player player) =>
                  player.m_customData.TryGetValue(KillsKey, out var raw) && int.TryParse(raw, out var kills) ? kills : 0;

              private static void Reward(Player player, int stage)
              {
                  var prefab = ObjectDB.instance.GetItemPrefab(Rewards[stage]);
                  var drop = Object.Instantiate(prefab, player.transform.position + Vector3.up, Quaternion.identity).GetComponent<ItemDrop>();
                  drop.SetStack(${P}.RewardAmount.Value * (stage + 1));
                  MessageHud.instance.QueueUnlockMsg(drop.m_itemData.GetIcon(), "$${snake}_title", stage + 1 == Targets.Length ? "$${snake}_complete" : "$${snake}_stage_done");
                  ${selfs(c, "player", `${P}.Power.Value`, true, ["blink"])}
              }
          }
      }`,
  );
  const command = file(
    "src/Patches/QuestCommand.cs",
    code`
      using HarmonyLib;

      namespace ${cls}.Patches
      {
          /// <summary>Adds a "${snake}" console command that prints quest progress.</summary>
          [HarmonyPatch(typeof(Terminal), nameof(Terminal.InitTerminal))]
          public static class QuestCommand
          {
              private static void Postfix()
              {
                  new Terminal.ConsoleCommand("${snake}", "shows ${input.modName} progress", args =>
                  {
                      var player = Player.m_localPlayer;
                      if (!player) return;
                      int kills = QuestTracker.Kills(player);
                      int stage = ${B}.StageFor(kills, ${P}.KillsPerStage.Value, QuestTracker.Targets.Length);
                      args.Context.AddString(stage >= QuestTracker.Targets.Length
                          ? $"{${P}.PluginName}: complete"
                          : $"{${P}.PluginName}: stage {stage + 1}, {QuestTracker.Targets[stage]} {${B}.ProgressInStage(kills, ${P}.KillsPerStage.Value)}/{${P}.KillsPerStage.Value}");
                  });
              }
          }
      }`,
  );
  return {
    settings: [
      nt("Quest", "KillsPerStage", perStage, "Kills needed to clear each stage.", [1, 100]),
      nt("Quest", "RewardAmount", n.xp, "Base reward stack, multiplied by the stage number.", [1, 999]),
      fl("Effects", "Power", n.power, "Strength of the stage-clear blessing.", [1, 50]),
    ],
    main,
    extra: [command],
    words: {
      [`${snake}_title`]: input.modName,
      [`${snake}_stage`]: "Stage $1: hunt the $2",
      [`${snake}_progress`]: `${input.modName}: $1 / $2`,
      [`${snake}_stage_done`]: "Stage cleared. The gods take notice.",
      [`${snake}_complete`]: "The saga is complete.",
    },
    balance: code`
      public static int StageFor(int kills, int perStage, int stages) => System.Math.Min(stages, kills / System.Math.Max(1, perStage));

      public static int ProgressInStage(int kills, int perStage) => kills % System.Math.Max(1, perStage);`,
    tests: code`
      [Theory]
      [InlineData(0, 0)]
      [InlineData(${perStage}, 1)]
      [InlineData(${perStage * 9}, 3)]
      public void StagesAdvanceAndCap(int kills, int expected) =>
          Assert.Equal(expected, ${c.B}.StageFor(kills, ${perStage}, 3));

      [Fact]
      public void ZeroPerStageDoesNotDivideByZero() => Assert.Equal(3, ${c.B}.StageFor(5, 0, 3));`,
