      fl("Effects", "Power", n.power, "Strength of each pulse.", [1, 50]),
      fl("Effects", "Radius", n.radius, "Pulse radius in meters.", [1, 30]),
      hk("Hotkeys", "AbilityKey", "G", "Fires a double-strength pulse."),
      fl("Hotkeys", "AbilityCooldown", n.cooldown, "Seconds between bursts.", [0.5, 120]),
    ],
    main: autoFirst ? production : pulse,
