function audioArch(c: Ctx): ArchOut {
  const { cls, snake, P, n, input } = c;
  const [, biome] = biomeFor(c);
  const main = file(
    "src/Patches/MusicPatches.cs",
    code`
      using System.Collections;
      using System.Collections.Generic;
      using System.IO;
      using HarmonyLib;
      using UnityEngine;
      using UnityEngine.Networking;

      namespace ${cls}.Patches
      {
          /// <summary>
          /// Registers music/${snake}_day.ogg and music/${snake}_night.ogg as NamedMusic and points the ${biome}'s
          /// environment music at them, so MusicMan crossfades between them with the day cycle.
          /// </summary>
          [HarmonyPatch]
          public static class MusicPatches
          {
              public const string DayTrack = "${snake}_day";
              public const string NightTrack = "${snake}_night";
              private static readonly Dictionary<string, AudioClip> Clips = new Dictionary<string, AudioClip>();

              public static IEnumerator LoadTracks(string folder)
              {
                  foreach (var track in new[] { DayTrack, NightTrack })
                  {
                      var path = Path.Combine(folder, track + ".ogg");
                      if (!File.Exists(path))
                      {
                          ${P}.Log.LogWarning($"Missing {path}");
                          continue;
                      }
                      using (var request = UnityWebRequestMultimedia.GetAudioClip("file:///" + path.Replace('\\\\', '/'), AudioType.OGGVORBIS))
                      {
                          yield return request.SendWebRequest();
                          if (request.result != UnityWebRequest.Result.Success)
                          {
                              ${P}.Log.LogError($"{track}: {request.error}");
                              continue;
                          }
                          var clip = DownloadHandlerAudioClip.GetContent(request);
                          clip.name = track;
                          Clips[track] = clip;
                      }
                  }
                  if (MusicMan.instance) Register(MusicMan.instance);
              }

              [HarmonyPatch(typeof(MusicMan), nameof(MusicMan.Awake)), HarmonyPostfix]
              private static void MusicManAwake(MusicMan __instance) => Register(__instance);

              [HarmonyPatch(typeof(EnvMan), nameof(EnvMan.Awake)), HarmonyPostfix]
              private static void EnvManAwake(EnvMan __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  foreach (var setup in __instance.m_biomes)
                  {
                      if (setup.m_biome != Heightmap.Biome.${biome}) continue;
                      setup.m_musicMorning = setup.m_musicDay = DayTrack;
                      setup.m_musicEvening = setup.m_musicNight = NightTrack;
                  }
              }

              private static void Register(MusicMan music)
              {
                  foreach (var pair in Clips)
                  {
                      if (music.m_music.Exists(m => m.m_name == pair.Key)) continue;
                      music.m_music.Add(new MusicMan.NamedMusic
                      {
                          m_name = pair.Key,
                          m_clips = new[] { pair.Value },
                          m_volume = ${P}.MusicVolume.Value,
                          m_fadeInTime = ${P}.FadeInSeconds.Value,
                          m_alwaysFadeout = true,
                          m_loop = true,
                          m_resume = true,
                          m_enabled = true,
                          m_ambientMusic = true,
                      });
                      ${P}.Log.LogInfo($"Registered music {pair.Key} ({pair.Value.length:0}s)");
                  }
              }
          }
      }`,
  );
  return {
    settings: [
      fl("Music", "MusicVolume", 0.8, "Volume of the new tracks.", [0, 1]),
      fl("Music", "FadeInSeconds", n.duration, "Crossfade time when the day cycle switches tracks.", [0, 30]),
    ],
    main,
    extra: [],
    words: { [`${snake}_title`]: input.modName },
    balance: tickBalance,
    tests: tickTests(c),
    usings: ["using System.IO;"],
    awake: `StartCoroutine(Patches.MusicPatches.LoadTracks(Path.Combine(Path.GetDirectoryName(Info.Location), "music")));`,
    refs: ["UnityEngine.AudioModule", "UnityEngine.UnityWebRequestModule", "UnityEngine.UnityWebRequestAudioModule"],
  };
}

/* ───────────── visual: EnvSetup color grade + post-processing ───────────── */

function hueOf([r, g, b]: [number, number, number]) {
  const max = Math.max(r, g, b);
  const d = max - Math.min(r, g, b);
  if (!d) return 0;
  const h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return Math.round((h * 60 + 360) % 360);
}

function visualArch(c: Ctx): ArchOut {
  const { cls, snake, P, B, n, input } = c;
  const main = file(
    "src/Patches/EnvColorGradePatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;

      namespace ${cls}.Patches
      {
          /// <summary>Tints every EnvSetup's ambient, fog and sun colors toward the configured hue, harder at night.</summary>
          [HarmonyPatch(typeof(EnvMan), nameof(EnvMan.Awake))]
          public static class EnvColorGradePatch
          {
              private static void Postfix(EnvMan __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  var tint = Color.HSVToRGB(${P}.Hue.Value / 360f, 0.35f, 1f);
                  float day = ${P}.Intensity.Value;
                  float night = day * ${P}.NightBoost.Value;

                  foreach (EnvSetup env in __instance.m_environments)
                  {
                      env.m_ambColorDay = Grade(env.m_ambColorDay, tint, day);
                      env.m_ambColorNight = Grade(env.m_ambColorNight, tint, night);
                      env.m_fogColorMorning = Grade(env.m_fogColorMorning, tint, day);
                      env.m_fogColorDay = Grade(env.m_fogColorDay, tint, day);
                      env.m_fogColorEvening = Grade(env.m_fogColorEvening, tint, day);
                      env.m_fogColorNight = Grade(env.m_fogColorNight, tint, night);
                      env.m_sunColorMorning = Grade(env.m_sunColorMorning, tint, day);
                      env.m_sunColorEvening = Grade(env.m_sunColorEvening, tint, day);
                      env.m_sunColorNight = Grade(env.m_sunColorNight, tint, night);
                  }
                  ${P}.Log.LogInfo($"Graded {__instance.m_environments.Count} environments");
              }

              private static Color Grade(Color color, Color tint, float intensity) => new Color(
                  ${B}.Grade(color.r, tint.r, intensity),
                  ${B}.Grade(color.g, tint.g, intensity),
                  ${B}.Grade(color.b, tint.b, intensity),
                  color.a);
          }
      }`,
  );
  const post = file(
    "src/Patches/PostProcessPatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;
      using UnityEngine.Rendering.PostProcessing;

      namespace ${cls}.Patches
      {
          /// <summary>Adds a global post-processing volume (color filter + bloom) on the game camera's volume layer.</summary>
          [HarmonyPatch(typeof(GameCamera), nameof(GameCamera.Awake))]
          public static class PostProcessPatch
          {
              private static PostProcessVolume _volume;

              private static void Postfix(GameCamera __instance)
              {
                  if (!${P}.Enabled.Value || _volume) return;
                  var layer = __instance.GetComponent<PostProcessLayer>();
                  if (!layer) return;

                  var grading = ScriptableObject.CreateInstance<ColorGrading>();
                  grading.enabled.Override(true);
                  grading.colorFilter.Override(Color.HSVToRGB(${P}.Hue.Value / 360f, 0.15f, 1f));
                  grading.saturation.Override(12f * ${P}.Intensity.Value);

                  var bloom = ScriptableObject.CreateInstance<Bloom>();
                  bloom.enabled.Override(true);
                  bloom.intensity.Override(${P}.Bloom.Value);

                  int volumeLayer = Mathf.RoundToInt(Mathf.Log(layer.volumeLayer.value, 2f));
                  _volume = PostProcessManager.instance.QuickVolume(volumeLayer, 100f, grading, bloom);
              }
          }
      }`,
  );
  return {
    settings: [
      nt("Grade", "Hue", hueOf(c.fx[0].tint), "Tint hue in degrees.", [0, 359]),
      fl("Grade", "Intensity", n.intensity, "How far colors are pulled toward the tint.", [0, 2]),
      fl("Grade", "NightBoost", 1.5, "Extra intensity applied to night colors.", [0.5, 3]),
      fl("Grade", "Bloom", Number((n.intensity * 3).toFixed(2)), "Bloom intensity.", [0, 10]),
    ],
    main,
    extra: [post],
    words: { [`${snake}_title`]: input.modName },
    balance: code`
      /// <summary>Moves a color channel toward channel * tint; intensity 2 applies the full tint.</summary>
      public static float Grade(float channel, float tint, float intensity) => channel + (channel * tint - channel) * Clamp(intensity, 0f, 2f) * 0.5f;`,
    tests: code`
      [Fact]
      public void WhiteTintIsANoOp() => Assert.Equal(0.5f, ${c.B}.Grade(0.5f, 1f, ${n.intensity}f), 4);

      [Fact]
      public void ZeroIntensityKeepsTheColor() => Assert.Equal(0.8f, ${c.B}.Grade(0.8f, 0.2f, 0f), 4);

      [Fact]
      public void FullIntensityAppliesTheTint() => Assert.Equal(0.5f, ${c.B}.Grade(1f, 0.5f, 5f), 4);`,
    refs: ["Unity.Postprocessing.Runtime"],
  };
}

