using BepInEx;
using BepInEx.Configuration;
using BepInEx.Logging;
using HarmonyLib;
using Jotunn.Managers;
using Jotunn.Utils;
using UnityEngine;

namespace TameableStormDrakes
{
    /// <summary>Tameable Storm Drakes: magic for Valheim. Forged by Cyrus (Yako) v1.</summary>
    [BepInPlugin(PluginGUID, PluginName, PluginVersion)]
    [BepInDependency(Jotunn.Main.ModGuid)]
    [NetworkCompatibility(CompatibilityLevel.EveryoneMustHaveMod, VersionStrictness.Minor)]
    public class TameableStormDrakesPlugin : BaseUnityPlugin
    {
        public const string PluginGUID = "com.cyrus.tameable_storm_drakes";
        public const string PluginName = "Tameable Storm Drakes";
        public const string PluginVersion = "1.0.0";
        public const string PrefabName = "TameableStormDrakes";

        internal static ManualLogSource Log;

        public static ConfigEntry<bool> Enabled;
        public static ConfigEntry<float> SpellDamage;
        public static ConfigEntry<int> EitrCost;
        public static ConfigEntry<float> EitrRegen;
        public static ConfigEntry<float> ProcChance;
        public static ConfigEntry<float> Power;

        private Harmony _harmony;

        private void Awake()
        {
            Log = Logger;
            BindConfig();

            _harmony = new Harmony(PluginGUID);
            _harmony.PatchAll();
            PrefabManager.OnVanillaPrefabsAvailable += Items.TameableStormDrakesStaff.Register;

            Logger.LogInfo($"{PluginName} v{PluginVersion} loaded");
        }

        private void BindConfig()
        {
            Enabled = Config.Bind("General", "Enabled", true, "Master switch for everything this mod adds.");
            SpellDamage = Config.Bind("Spell", "SpellDamage", 67f, new ConfigDescription("Elemental damage per projectile.", new AcceptableValueRange<float>(1f, 400f)));
            EitrCost = Config.Bind("Spell", "EitrCost", 27, new ConfigDescription("Eitr spent per cast.", new AcceptableValueRange<int>(0, 150)));
            EitrRegen = Config.Bind("Spell", "EitrRegen", 1.58f, new ConfigDescription("Eitr regeneration multiplier while equipped.", new AcceptableValueRange<float>(1f, 3f)));
            ProcChance = Config.Bind("Effects", "ProcChance", 0.31f, new ConfigDescription("Chance for on-hit effects to trigger.", new AcceptableValueRange<float>(0f, 1f)));
            Power = Config.Bind("Effects", "Power", 13.4f, new ConfigDescription("Strength of the on-hit effects.", new AcceptableValueRange<float>(1f, 50f)));
        }

        private void OnDestroy() => _harmony?.UnpatchSelf();
    }

    /// <summary>Pure balance math with no Unity types, so it can be unit tested outside the game.</summary>
    public static class TameableStormDrakesBalance
    {
        /// <summary>Share of the base elemental damage added per upgrade (Valheim's m_damagesPerLevel).</summary>
        public const float PerLevelRatio = 0.25f;

        /// <summary>Mirrors ItemDrop.ItemData.GetDamage: base + perLevel * (quality - 1), capped at four upgrades.</summary>
        public static float DamageAtQuality(float baseDamage, int quality) => baseDamage + baseDamage * PerLevelRatio * (Clamp(quality, 1, 4) - 1);

        public static bool Procs(float chance, float roll) => roll < Clamp(chance, 0f, 1f);

        public static float Clamp(float value, float min, float max) => value < min ? min : value > max ? max : value;

        public static int Clamp(int value, int min, int max) => value < min ? min : value > max ? max : value;
    }
}
using Jotunn.Configs;
using Jotunn.Entities;
using Jotunn.Managers;
using UnityEngine;

namespace TameableStormDrakes.Items
{
    /// <summary>Builds the staff from StaffIceShards through Jötunn once vanilla prefabs are available.</summary>
    internal static class TameableStormDrakesStaff
    {
        private const string BasePrefab = "StaffIceShards";

        public static void Register()
        {
            try
            {
                var staff = new CustomItem(TameableStormDrakesPlugin.PrefabName, BasePrefab, new ItemConfig
                {
                    Name = "$item_tameable_storm_drakes",
                    Description = "$item_tameable_storm_drakes_description",
                    CraftingStation = CraftingStations.GaldrTable,
                    MinStationLevel = 2,
                    Requirements = new[]
                    {
                        new RequirementConfig("YggdrasilWood", 12, 4),
                        new RequirementConfig("Eitr", 16, 8),
                        new RequirementConfig("FreezeGland", 8, 4),
                        new RequirementConfig("Thunderstone", 8, 4),
                    },
                });

                var shared = staff.ItemDrop.m_itemData.m_shared;
                shared.m_damages.m_frost = TameableStormDrakesPlugin.SpellDamage.Value;
                shared.m_damagesPerLevel.m_frost = TameableStormDrakesPlugin.SpellDamage.Value * TameableStormDrakesBalance.PerLevelRatio;
                shared.m_damages.m_lightning = TameableStormDrakesPlugin.SpellDamage.Value;
                shared.m_damagesPerLevel.m_lightning = TameableStormDrakesPlugin.SpellDamage.Value * TameableStormDrakesBalance.PerLevelRatio;
                shared.m_attack.m_attackEitr = TameableStormDrakesPlugin.EitrCost.Value;
                shared.m_equipStatusEffect = CreateAttunement(shared);

                ItemManager.Instance.AddItem(staff);
                TameableStormDrakesPlugin.Log.LogInfo($"Added {staff.ItemDrop.name} (cloned from {BasePrefab})");
            }
            finally
            {
                PrefabManager.OnVanillaPrefabsAvailable -= Register;
            }
        }

        /// <summary>Equip effect: faster eitr regeneration while the staff is in hand.</summary>
        private static StatusEffect CreateAttunement(ItemDrop.ItemData.SharedData shared)
        {
            var attunement = ScriptableObject.CreateInstance<SE_Stats>();
            attunement.name = "SE_TameableStormDrakes";
            attunement.m_name = "$se_tameable_storm_drakes";
            attunement.m_tooltip = "$se_tameable_storm_drakes_tooltip";
            attunement.m_icon = shared.m_icons[0];
            attunement.m_eitrRegenMultiplier = TameableStormDrakesPlugin.EitrRegen.Value;
            ItemManager.Instance.AddStatusEffect(new CustomStatusEffect(attunement, fixReference: false));
            return attunement;
        }
    }
}
