using System.Collections.Generic;
using HarmonyLib;
using UnityEngine;
using Object = UnityEngine.Object;

namespace TameableStormDrakes.Patches
{
    /// <summary>Character.Damage runs on the attacker's client, so the effects fire where the swing happened.</summary>
    [HarmonyPatch(typeof(Character), nameof(Character.Damage))]
    public static class TameableStormDrakesHitPatch
    {
        private static bool _applying;

        private static void Postfix(Character __instance, HitData hit)
        {
            if (_applying || !TameableStormDrakesPlugin.Enabled.Value || hit == null || __instance.IsDead()) return;
            if (!(hit.GetAttacker() is Player player) || player != Player.m_localPlayer) return;

            var weapon = player.GetCurrentWeapon();
            if (weapon?.m_dropPrefab == null || weapon.m_dropPrefab.name != TameableStormDrakesPlugin.PrefabName) return;
            if (!TameableStormDrakesBalance.Procs(TameableStormDrakesPlugin.ProcChance.Value, Random.value)) return;

            var power = TameableStormDrakesPlugin.Power.Value;
            _applying = true;
            try
            {
                __instance.GetSEMan().AddStatusEffect(ObjectDB.instance.GetStatusEffect("Frost".GetStableHashCode()), resetTime: true);
                Object.Instantiate(ZNetScene.instance.GetPrefab("lightningAOE"), __instance.transform.position, Quaternion.identity);
            }
            finally
            {
                _applying = false;
            }
        }
    }
}
