using Xunit;

namespace TameableStormDrakes.Tests
{
    public class TameableStormDrakesBalanceTests
    {
        [Theory]
        [InlineData(1, 67f)]
        [InlineData(3, 100.5f)]
        [InlineData(4, 117.25f)]
        public void ElementalDamageScalesPerUpgrade(int quality, float expected) =>
            Assert.Equal(expected, TameableStormDrakesBalance.DamageAtQuality(67f, quality), 2);

        [Fact]
        public void QualityIsCappedAtFour() =>
            Assert.Equal(TameableStormDrakesBalance.DamageAtQuality(67f, 4), TameableStormDrakesBalance.DamageAtQuality(67f, 9));

        [Fact]
        public void ProcChanceIsClampedToCertainty()
        {
            Assert.True(TameableStormDrakesBalance.Procs(5f, 0.999f));
            Assert.False(TameableStormDrakesBalance.Procs(-1f, 0f));
        }

        [Theory]
        [InlineData(-5f, 0f)]
        [InlineData(0.35f, 0.35f)]
        [InlineData(9f, 1f)]
        public void ClampKeepsConfigValuesInRange(float raw, float expected) =>
            Assert.Equal(expected, TameableStormDrakesBalance.Clamp(raw, 0f, 1f));
    }
}
