namespace TameableStormDrakes.Patches
{
    /// <summary>Clones Hatchling into TameableStormDrakes when ZNetScene builds its prefab table.</summary>
    [HarmonyPatch(typeof(ZNetScene), nameof(ZNetScene.Awake))]
    public static class CreatureRegistration
    {
        private const string BasePrefab = "Hatchling"; // the Drake's internal prefab name
        private static GameObject _container;

        private static void Postfix(ZNetScene __instance)
        {
            var source = __instance.GetPrefab(BasePrefab);
            if (!source || __instance.GetPrefab(TameableStormDrakesPlugin.PrefabName)) return;
            if (!_container)
            {
                _container = new GameObject("TameableStormDrakes_Prefabs");
                _container.SetActive(false);
                Object.DontDestroyOnLoad(_container);
            }

            var prefab = Object.Instantiate(source, _container.transform, false);
            prefab.name = TameableStormDrakesPlugin.PrefabName;

            var character = prefab.GetComponent<Character>();
            character.m_name = "$enemy_tameable_storm_drakes";
            character.m_health = TameableStormDrakesPlugin.Health.Value;
            character.m_runSpeed *= 1f + TameableStormDrakesPlugin.SpeedBonus.Value;
            var ai = prefab.GetComponent<MonsterAI>();
            ai.m_consumeItems = new[] { "RawMeat", "DeerMeat", "LoxMeat" }
                .Select(name => __instance.GetPrefab(name))
                .Where(food => food != null)
                .Select(food => food.GetComponent<ItemDrop>())
                .ToList();
            ai.m_consumeSearchRange = 12f;

            if (!prefab.TryGetComponent(out Tameable tameable))
            {
                // Not tameable in vanilla: add the component and borrow the wolf's taming effects.
                tameable = prefab.AddComponent<Tameable>();
                var wolf = __instance.GetPrefab("Wolf").GetComponent<Tameable>();
                tameable.m_tamedEffect = wolf.m_tamedEffect;
                tameable.m_sootheEffect = wolf.m_sootheEffect;
                tameable.m_petEffect = wolf.m_petEffect;
            }
            tameable.m_tamingTime = TameableStormDrakesPlugin.TamingTime.Value;
            tameable.m_fedDuration = 600f;
            tameable.m_commandable = true;
            // Borrow the Lox saddle rig. Sadle resolves its Character with GetComponentInParent when the clone spawns.
            var lox = __instance.GetPrefab("Lox").GetComponent<Tameable>();
            var saddle = Object.Instantiate(lox.m_saddle.gameObject, prefab.transform, false);
            saddle.name = lox.m_saddle.gameObject.name;
            tameable.m_saddle = saddle.GetComponent<Sadle>();
            tameable.m_saddleItem = lox.m_saddleItem;
            tameable.m_saddle.m_maxStamina = TameableStormDrakesPlugin.RideStamina.Value;
            tameable.m_saddle.m_attachPoint.localPosition += new Vector3(0f, 0.45f, -0.2f);

            prefab.AddComponent<TameableStormDrakesBrain>();
            __instance.m_prefabs.Add(prefab);
            __instance.m_namedPrefabs[prefab.name.GetStableHashCode()] = prefab;
            TameableStormDrakesPlugin.Log.LogInfo($"Registered {prefab.name} (cloned from {BasePrefab})");
        }
    }

    /// <summary>Runs only on the client that owns the ZDO, so effects are applied exactly once.</summary>
    public class TameableStormDrakesBrain : MonoBehaviour
    {
        private Character _character;
        private ZNetView _nview;
        private float _timer;

        private void Awake()
        {
            _character = GetComponent<Character>();
            _nview = GetComponent<ZNetView>();
        }

        private void Update()
        {
            if (!_nview || !_nview.IsValid() || !_nview.IsOwner() || _character.IsDead() || !TameableStormDrakesPlugin.Enabled.Value) return;
            var rider = Player.m_localPlayer;
            if (!rider || !rider.IsRiding() || Vector3.Distance(rider.transform.position, transform.position) > 4f)
            {
                _timer = 0f;
                return;
            }
            _timer += Time.deltaTime;
            if (_timer < TameableStormDrakesPlugin.AbilityCooldown.Value) return;
            _timer = 0f;
            rider.AddStamina(TameableStormDrakesPlugin.Power.Value);
        }
    }
}
