namespace TameableStormDrakes.Patches
{
    /// <summary>Elemental damage and on-hit effects for attacks made by TameableStormDrakes.</summary>
    [HarmonyPatch(typeof(Character), nameof(Character.Damage))]
    public static class TameableStormDrakesAttackPatch
    {
        private static bool _applying;

        private static void Prefix(HitData hit)
        {
            if (_applying || hit == null || !IsOurs(hit.GetAttacker())) return;
            hit.m_damage.m_frost += TameableStormDrakesPlugin.ElementalDamage.Value;
            hit.m_damage.m_lightning += TameableStormDrakesPlugin.ElementalDamage.Value;
        }

        private static void Postfix(Character __instance, HitData hit)
        {
            var attacker = hit?.GetAttacker();
            if (_applying || !IsOurs(attacker) || __instance.IsDead()) return;
            var power = TameableStormDrakesPlugin.Power.Value;
            _applying = true;
            try
            {
                __instance.GetSEMan().AddStatusEffect(ObjectDB.instance.GetStatusEffect("Frost".GetStableHashCode()), resetTime: true);
                Object.Instantiate(ZNetScene.instance.GetPrefab("lightningAOE"), __instance.transform.position, Quaternion.identity);
            }
            finally
            {
                _applying = false;
            }
        }

        private static bool IsOurs(Character character) =>
            character && TameableStormDrakesPlugin.Enabled.Value && Utils.GetPrefabName(character.gameObject) == TameableStormDrakesPlugin.PrefabName;
    }
}

