// Usage: node batch.mjs <jobs.json>  where jobs = [[dir, prompt, model], ...]
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const jobs = JSON.parse(fs.readFileSync(path.resolve(here, process.argv[2]), "utf8"));

async function run([dir, prompt, model]) {
  const res = await fetch("http://localhost:3000/api/generate", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ prompt, model }),
  });
  const text = await res.text();
  const files = new Map();
  let route;
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const ev = JSON.parse(line);
    if (ev.type === "route") route = ev;
    if (ev.type === "file") files.set(ev.path, "");
    if (ev.type === "chunk") files.set(ev.path, files.get(ev.path) + ev.text);
    if (ev.type === "error") console.log("ERROR", ev.message);
  }
  const out = path.join(here, "out", dir);
  fs.rmSync(out, { recursive: true, force: true });
  const lines = [`${dir}: ${route?.gameId} / ${route?.category} / ${route?.modName} [${model}]`];
  for (const [p, content] of files) {
    const dest = path.join(out, p);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.writeFileSync(dest, content);
    lines.push(`  ${p} (${content.split("\n").length})`);
  }
  return lines.join("\n");
}

const results = await Promise.all(jobs.map(run));
console.log(results.join("\n"));

