namespace HealingAmuletItem.Patches
{
    [HarmonyPatch(typeof(Player), nameof(Player.Update))]
    public static class HealingAmuletItemAbilityPatch
    {
        private static float _cooldown;

        private static void Postfix(Player __instance)
        {
            if (__instance != Player.m_localPlayer || !HealingAmuletItemPlugin.Enabled.Value) return;
            if (_cooldown > 0f)
            {
                _cooldown -= Time.deltaTime;
                return;
            }
            if (!__instance.TakeInput() || !HealingAmuletItemPlugin.AbilityKey.Value.IsDown()) return;

            var equipped = __instance.GetInventory().GetEquippedItems().Find(i => i.m_dropPrefab && i.m_dropPrefab.name == HealingAmuletItemPlugin.PrefabName);
            if (equipped == null) return;

            var targets = new List<Character>();
            Character.GetCharactersInRange(__instance.transform.position, HealingAmuletItemPlugin.Radius.Value, targets);
            foreach (var target in targets)
            {
                if (target == __instance || target.IsDead() || !BaseAI.IsEnemy(__instance, target)) continue;
                var strike = new HitData { m_point = target.GetCenterPoint() };
                strike.m_damage.m_blunt = HealingAmuletItemPlugin.Power.Value;
                strike.SetAttacker(__instance);
                target.Damage(strike);
            }
            __instance.Heal(HealingAmuletItemPlugin.Power.Value * 0.5f, showText: true);
            _cooldown = HealingAmuletItemPlugin.AbilityCooldown.Value;
        }
    }
}
