namespace AutoSmelting.Patches
{
    /// <summary>A passive pulse every Interval seconds, plus an active burst on the hotkey.</summary>
    [HarmonyPatch(typeof(Player), nameof(Player.Update))]
    public static class PlayerUpdatePatch
    {
        private static float _timer;
        private static float _cooldown;

        private static void Postfix(Player __instance)
        {
            if (__instance != Player.m_localPlayer || !AutoSmeltingPlugin.Enabled.Value || __instance.IsDead()) return;
            _cooldown -= Time.deltaTime;
            _timer += Time.deltaTime;

            if (AutoSmeltingBalance.Ready(_timer, AutoSmeltingPlugin.Interval.Value))
            {
                _timer = 0f;
                Pulse(__instance, AutoSmeltingBalance.NightScaled(AutoSmeltingPlugin.Power.Value, EnvMan.instance.IsNight()));
            }

            if (_cooldown <= 0f && __instance.TakeInput() && AutoSmeltingPlugin.AbilityKey.Value.IsDown())
            {
                _cooldown = AutoSmeltingPlugin.AbilityCooldown.Value;
                Pulse(__instance, AutoSmeltingPlugin.Power.Value * 2f);
                __instance.Message(MessageHud.MessageType.TopLeft, "$auto_smelting_burst");
            }
        }

        private static void Pulse(Player player, float power)
        {
            var targets = new List<Character>();
            Character.GetCharactersInRange(player.transform.position, AutoSmeltingPlugin.Radius.Value, targets);
            foreach (var target in targets)
            {
                if (target == player || target.IsDead() || !BaseAI.IsEnemy(player, target)) continue;
                var strike = new HitData { m_point = target.GetCenterPoint() };
                strike.m_damage.m_blunt = power;
                strike.SetAttacker(player);
                target.Damage(strike);
            }
        }
    }
}
