namespace MoonlitHuntingQuestLine.Patches
{
    /// <summary>
    /// Three hunting stages, saved in Player.m_customData so progress survives logout.
    /// Character.OnDeath runs on the ZDO owner, which is usually the nearest player.
    /// </summary>
    [HarmonyPatch]
    public static class QuestTracker
    {
        public const string KillsKey = "com.cyrus.moonlit_hunting_quest_line.kills";
        public static readonly string[] Targets = { "Skeleton", "Ghost", "Wraith" };
        private static readonly string[] Rewards = { "Coins", "Coins", "Crystal" };

        [HarmonyPatch(typeof(Character), nameof(Character.OnDeath)), HarmonyPostfix]
        private static void OnDeath(Character __instance)
        {
            var player = Player.m_localPlayer;
            if (!player || !MoonlitHuntingQuestLinePlugin.Enabled.Value || __instance.m_lastHit?.GetAttacker() != player) return;
            if (!EnvMan.instance.IsNight()) return; // the hunt only counts under the moon

            int kills = Kills(player);
            int perStage = MoonlitHuntingQuestLinePlugin.KillsPerStage.Value;
            int stage = MoonlitHuntingQuestLineBalance.StageFor(kills, perStage, Targets.Length);
            if (stage >= Targets.Length || Utils.GetPrefabName(__instance.gameObject) != Targets[stage]) return;

            kills++;
            player.m_customData[KillsKey] = kills.ToString();
            if (MoonlitHuntingQuestLineBalance.StageFor(kills, perStage, Targets.Length) == stage)
            {
                MessageHud.instance.ShowMessage(MessageHud.MessageType.TopLeft,
                    Localization.instance.Localize("$moonlit_hunting_quest_line_progress", MoonlitHuntingQuestLineBalance.ProgressInStage(kills, perStage).ToString(), perStage.ToString()));
                return;
            }

            Reward(player, stage);
            if (stage + 1 < Targets.Length)
            {
                var next = ZNetScene.instance.GetPrefab(Targets[stage + 1]).GetComponent<Character>().m_name;
                MessageHud.instance.ShowMessage(MessageHud.MessageType.Center,
                    Localization.instance.Localize("$moonlit_hunting_quest_line_stage", (stage + 2).ToString(), Localization.instance.Localize(next)));
            }
        }

        public static int Kills(Player player) =>
            player.m_customData.TryGetValue(KillsKey, out var raw) && int.TryParse(raw, out var kills) ? kills : 0;

        private static void Reward(Player player, int stage)
        {
            var prefab = ObjectDB.instance.GetItemPrefab(Rewards[stage]);
            var drop = Object.Instantiate(prefab, player.transform.position + Vector3.up, Quaternion.identity).GetComponent<ItemDrop>();
            drop.SetStack(MoonlitHuntingQuestLinePlugin.RewardAmount.Value * (stage + 1));
            MessageHud.instance.QueueUnlockMsg(drop.m_itemData.GetIcon(), "$moonlit_hunting_quest_line_title", stage + 1 == Targets.Length ? "$moonlit_hunting_quest_line_complete" : "$moonlit_hunting_quest_line_stage_done");
        }
    }
}
