/** Pulses the effects from `src` (a Player): per-enemy hits around it, then its own buffs. */
function castBlock(c: Ctx, src: string, power: string, radius: string) {
  const self = selfs(c, src, power, true);
  const perTarget = hits(c, "target", src, power);
  if (dmgsOf(c).length || (!perTarget.length && !self.length)) perTarget.unshift(strike(c, "target", src, power));
  const loop = code`
    var targets = new List<Character>();
    Character.GetCharactersInRange(${src}.transform.position, ${radius}, targets);
    foreach (var target in targets)
    {
        if (target == ${src} || target.IsDead() || !BaseAI.IsEnemy(${src}, target)) continue;
        ${perTarget}
    }`;
  return code`
    ${perTarget.length ? loop : ""}
    ${self}`;
}

/** In-game name: drops filler like "Item" or "Tameable"; entities get a singular noun. */
function displayName(c: Ctx, singular = false) {
  const all = c.input.modName.split(/\s+/);
  const words = all.filter((w) => !/^(items?|creatures?|vehicles?|mechanics?|tameable|rideable|mod)$/i.test(w));
  const out = words.length ? words : all;
  if (singular) out[out.length - 1] = out[out.length - 1].replace(/ves$/i, "f").replace(/([^s])s$/i, "$1");
  return out.join(" ");
}

