function productionPatch(c: Ctx): ModFile {
  const { cls, P, B } = c;
  const speed = `${P}.ProductionSpeed.Value`;
  return file(
    "src/Patches/ProductionPatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;

      namespace ${cls}.Patches
      {
          /// <summary>Each building keeps its own copy of these fields, so scaling them in Awake is per-instance and safe.</summary>
          [HarmonyPatch]
          public static class ProductionPatch
          {
              // Smelter covers the smelter, blast furnace, charcoal kiln, spinning wheel and windmill.
              [HarmonyPatch(typeof(Smelter), nameof(Smelter.Awake)), HarmonyPostfix]
              private static void SmelterAwake(Smelter __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  __instance.m_secPerProduct = ${B}.ProductionSeconds(__instance.m_secPerProduct, ${speed});
                  __instance.m_maxOre = Mathf.RoundToInt(__instance.m_maxOre * Mathf.Sqrt(${speed}));
              }

              [HarmonyPatch(typeof(Fermenter), nameof(Fermenter.Awake)), HarmonyPostfix]
              private static void FermenterAwake(Fermenter __instance)
              {
                  if (${P}.Enabled.Value) __instance.m_fermentationDuration = ${B}.ProductionSeconds(__instance.m_fermentationDuration, ${speed});
              }

              [HarmonyPatch(typeof(CookingStation), nameof(CookingStation.Awake)), HarmonyPostfix]
              private static void CookingStationAwake(CookingStation __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  foreach (var conversion in __instance.m_conversion)
                      conversion.m_cookTime = ${B}.ProductionSeconds(conversion.m_cookTime, ${speed});
              }
          }
      }`,
  );
}

/** Automation mechanic: tops up smelters and kilns from nearby chests. */
function feederPatch(c: Ctx): ModFile {
  const { cls, P } = c;
  return file(
    "src/Patches/SmelterFeederPatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;

      namespace ${cls}.Patches
      {
          /// <summary>
          /// UpdateSmelter ticks once a second on the ZDO owner. Pulls fuel and ore from unlocked chests in range
          /// through the same RPCs the player's "add ore" interaction uses, so every client stays in sync.
          /// </summary>
          [HarmonyPatch(typeof(Smelter), nameof(Smelter.UpdateSmelter))]
          public static class SmelterFeederPatch
          {
              private static readonly Collider[] Hits = new Collider[64];

              private static void Postfix(Smelter __instance)
              {
                  if (!${P}.Enabled.Value || !__instance.m_nview.IsValid() || !__instance.m_nview.IsOwner()) return;
                  int count = Physics.OverlapSphereNonAlloc(__instance.transform.position, ${P}.FeedRadius.Value, Hits, LayerMask.GetMask("piece", "piece_nonsolid"));

                  for (int i = 0; i < count; i++)
                  {
                      var container = Hits[i].GetComponentInParent<Container>();
                      if (!container || container.IsInUse() || !container.m_nview.IsOwner()) continue;
                      var inventory = container.GetInventory();

                      if (__instance.m_fuelItem && __instance.GetFuel() < __instance.m_maxFuel - 1)
                      {
                          var fuel = __instance.m_fuelItem.m_itemData.m_shared.m_name;
                          if (inventory.HaveItem(fuel))
                          {
                              inventory.RemoveItem(fuel, 1);
                              __instance.m_nview.InvokeRPC("RPC_AddFuel");
                          }
                      }

                      if (__instance.GetQueueSize() >= __instance.m_maxOre) continue;
                      foreach (var conversion in __instance.m_conversion)
                      {
                          var ore = conversion.m_from.m_itemData.m_shared.m_name;
                          if (!inventory.HaveItem(ore)) continue;
                          inventory.RemoveItem(ore, 1);
                          __instance.m_nview.InvokeRPC("RPC_AddOre", conversion.m_from.gameObject.name);
                          break;
                      }
                  }
              }
          }
      }`,
  );
}

