    /// <summary>Pure balance math with no Unity types, so it can be unit tested outside the game.</summary>
    public static class AutoSmeltingBalance
    {

        /// <summary>Production time after the speed multiplier; never slower than vanilla.</summary>
        public static float ProductionSeconds(float seconds, float speed) => seconds / Clamp(speed, 1f, 10f);

        public static float Clamp(float value, float min, float max) => value < min ? min : value > max ? max : value;

        public static int Clamp(int value, int min, int max) => value < min ? min : value > max ? max : value;
    }
}
using Xunit;

namespace AutoSmelting.Tests
{
    public class AutoSmeltingBalanceTests
    {

        [Theory]
        [InlineData(30f, 2f, 15f)]
        [InlineData(30f, 0.2f, 30f)]
        public void ProductionIsNeverSlowerThanVanilla(float seconds, float speed, float expected) =>
            Assert.Equal(expected, AutoSmeltingBalance.ProductionSeconds(seconds, speed));

        [Theory]
        [InlineData(-5f, 0f)]
        [InlineData(0.35f, 0.35f)]
        [InlineData(9f, 1f)]
        public void ClampKeepsConfigValuesInRange(float raw, float expected) =>
            Assert.Equal(expected, AutoSmeltingBalance.Clamp(raw, 0f, 1f));
    }
}

