using BepInEx;
using BepInEx.Configuration;
using BepInEx.Logging;
using HarmonyLib;
using UnityEngine;

namespace FrostAxe
{
    /// <summary>Frost Axe: weapons for Valheim. Forged by Cyrus (Yako) v1.</summary>
    [BepInPlugin(PluginGUID, PluginName, PluginVersion)]
    public class FrostAxePlugin : BaseUnityPlugin
    {
        public const string PluginGUID = "com.cyrus.frost_axe";
        public const string PluginName = "Frost Axe";
        public const string PluginVersion = "1.0.0";
        public const string PrefabName = "FrostAxe";

        internal static ManualLogSource Log;

        public static ConfigEntry<bool> Enabled;
        public static ConfigEntry<float> ElementalDamage;
        public static ConfigEntry<float> AttackForce;
        public static ConfigEntry<float> ProcChance;
        public static ConfigEntry<float> Power;

        private Harmony _harmony;

        private void Awake()
        {
            Log = Logger;
                Object.DontDestroyOnLoad(_container);
            }
            _prefab = Object.Instantiate(source, _container.transform, false);
            _prefab.name = FrostAxePlugin.PrefabName;
            return _prefab;
        }

        private static Recipe CreateRecipe(ObjectDB db, GameObject prefab)
        {
            var template = db.GetRecipe(db.GetItemPrefab("AxeIron").GetComponent<ItemDrop>().m_itemData);
            var recipe = ScriptableObject.CreateInstance<Recipe>();
            recipe.name = "Recipe_" + prefab.name;
            recipe.m_item = prefab.GetComponent<ItemDrop>();
            recipe.m_amount = 1;
            recipe.m_craftingStation = template ? template.m_craftingStation : null;
            recipe.m_minStationLevel = template ? template.m_minStationLevel + 1 : 1;
            recipe.m_resources = new[]
            {
                Requirement(db, "Iron", 20, 10),
                Requirement(db, "ElderBark", 6, 2),
                Requirement(db, "FreezeGland", 8, 4),
            };
            return recipe;
        }

        private static Piece.Requirement Requirement(ObjectDB db, string item, int amount, int perLevel) => new Piece.Requirement
        {
            m_resItem = db.GetItemPrefab(item).GetComponent<ItemDrop>(),
            m_amount = amount,
            m_amountPerLevel = perLevel,
            m_recover = true,
        {
            if (_applying || !FrostAxePlugin.Enabled.Value || hit == null || __instance.IsDead()) return;
            if (!(hit.GetAttacker() is Player player) || player != Player.m_localPlayer) return;

            var weapon = player.GetCurrentWeapon();
            if (weapon?.m_dropPrefab == null || weapon.m_dropPrefab.name != FrostAxePlugin.PrefabName) return;
            if (!FrostAxeBalance.Procs(FrostAxePlugin.ProcChance.Value, Random.value)) return;

            var power = FrostAxePlugin.Power.Value;
            _applying = true;
            try
            {
                __instance.GetSEMan().AddStatusEffect(ObjectDB.instance.GetStatusEffect("Frost".GetStableHashCode()), resetTime: true);
            }
            finally
            {
                _applying = false;
            }
        }
    }
}
